/**
 * mercariCategoryMap.ts -- DATA for services/mercariCategoryResolver.ts: which Mercari leaf category an item
 * belongs in (S-EXT-MERCARI-CATEGORY-MAP, 2026-10-05). Dependency-free: no imports, no env, no I/O.
 * Every number below is a node id from config/mercariCategoryTree.ts; the Jest suite asserts that every
 * target exists and is a harvested LEAF (a level-2 node under a group whose leaves were read from Mercari),
 * so a typo or a Mercari tree change fails CI instead of mis-filing items. The tree is PARTIAL (see its
 * header): an item type whose Mercari group was not harvested simply has no rule and resolves to null.
 *
 * LAYER 1 -- MERCARI_CURATED_BY_EBAY_ID: keyed by the eBay numeric leaf category id stored on
 *   Item.ebayCategoryId. Seeded from the ids that occur on production Items (read-only export of 351 items,
 *   2026-10-04) plus the card ids pinned in cardEbayCategories.ts. Only ids specific enough to point at ONE
 *   Mercari leaf are listed; a broad eBay id ("Books", "Replacement Parts") is deliberately absent so the
 *   item's own words decide.
 * LAYER 2 -- MERCARI_RULES: ordered keyword rules over eBay category name + breadcrumb + title (+ the
 *   description for a few prefixes), specific before generic. First matching rule wins. A rule whose target
 *   is `null` is a deliberate BLANK: no honest Mercari home exists (or Mercari forbids the item), so the
 *   later scored layer must not guess one.
 *
 * Pattern syntax (strings, compiled by the resolver, case-insensitive, matched against text that has been
 * lower-cased, accent-folded, with apostrophes removed and every other non-alphanumeric run turned into one
 * space, and "&" turned into " and "; so write "t shirts?" not "t-shirt", "mens" not "men's"): each pattern is
 * an alternation body wrapped as \b(?:body)\b. Prefix "cat:" tests only the eBay category name + breadcrumb,
 * "title:" only the title, "desc:" title + category + description; no prefix = category + title. A rule
 * matches when ALL of its `all` patterns match and NONE of its `none` patterns match.
 *
 * Department-split targets (apparel, golf clubs) are {women, men, girls, boys, any}. The department is read
 * from explicit words only (mens, womens, boys, girls ...); when it is not stated and no `any` leaf is given
 * the item resolves to nothing (blank beats wrong). Only women and men leaves were harvested, so a boys or
 * girls item in these families also resolves to nothing.
 */

export interface MercariDeptMap {
  women?: number;
  men?: number;
  girls?: number;
  boys?: number;
  /** Used only when the department is not stated (an item type that exists under one department only). */
  any?: number;
}
export type MercariTarget = number | MercariDeptMap;

export type MercariCuratedEntry =
  | MercariTarget
  | { split: Array<[string, MercariTarget | null]>; fallback?: MercariTarget | null };

export interface MercariRuleDef {
  id: string;
  /** null = deliberate blank (see header). */
  target: MercariTarget | null;
  all: string[];
  none?: string[];
}

const rule = (id: string, target: MercariTarget | null, all: string[], none?: string[]): MercariRuleDef =>
  none ? { id, target, all, none } : { id, target, all };
/** A deliberate blank: matching items get NO Mercari category (never guessed by the scored layer). */
const blank = (id: string, all: string[], none?: string[]): MercariRuleDef => rule(id, null, all, none);

/** Words that mean "this is a collectible or a piece of merchandise about the thing, not the thing itself". */
const NOT_MEMORABILIA = 'cards?|signed|autographed|memorabilia|commemorative|ornaments?|figurines?|bobbleheads?|miniatures?|minis?|posters?|prints?|plaques?|pennants?|tickets?|programs?|stickers?|mugs?|keychains?|pins?|patch(es)?|magnets?|statues?|replicas?|souvenirs?|toys?|plush|dvds?|books?|magazines?';
/** Words that mean an accessory or part of a product rather than the product. */
const NOT_PARTS = 'parts?|replacement|repair|covers?|cases?|bags? only|stands?|mounts?|holders?|brackets?|cables?|cords?|adapters?|chargers?|batter(y|ies)|filters?|kits?';
/** EBay Motors / vehicle-part categories: a lamp, hose, pump, fan or heater in these is a vehicle part, never a home item. */
const NOT_MOTORS = 'cat:ebay motors|cat:car and truck|cat:motorcycle parts|cat:vehicle parts|cat:automotive';

